INSERT INTO prompts (title, content, category, author) VALUES ('Profile / Avatar - Neon Gel Lighting Studio Portrait', 'A hyper-photorealistic studio portrait of the same female subject under colored gel lighting.

Scene:
Dark background with {argument name="neon colors" default="red and blue"} neon lighting hitting opposite sides of her face, soft shadows and glow transitions.

Camera settings:
CCD digicam base with visible grain, slight color inconsistency enhanced by neon lights, direct flash subtly filling shadows. Portra 400 tones layered: warm skin balance maintained despite colored lighting, soft highlight roll-off.

Makeup:
Rosy complexion, dewy pores visible, feathery brows, thin wing liner, wispy lashes, grey contacts reflecting colored light, pink gloss lips.

Hair:
{argument name="hair style" default="Long layered hair with inward upward curls"}, softly moving, slightly windswept, catching colored light on edges.

Negative prompt:
no cyberpunk overgrading, no oversaturated neon, no plastic skin', 'general', 'Chryz leen');
INSERT INTO prompts (title, content, category, author) VALUES ('Profile / Avatar - Hyper-Realistic Charcoal Pensive Portrait', 'A hyper-realistic charcoal and graphite portrait of a handsome man with {argument name="hair style" default="thick, dark curly hair"}. He is leaning his head against his hand in a pensive, intense pose. Use {argument name="lighting" default="deep chiaroscuro lighting"} to create dramatic highlights on his face and forearm, with the background dissolving into {argument name="background style" default="heavy, textured black charcoal strokes"}. Every detail is meticulously rendered: the individual curls of his hair, the subtle stubble on his jaw, and the reflective moisture in his eyes. The style should feel like a traditional fine-art sketch on textured paper, featuring visible cross-hatching and blended smudges for depth. Monochrome, high contrast, moody, and cinematic.', 'general', 'Minahil');
