INSERT INTO prompts (title, content, category, author) VALUES ('Profile / Avatar - Modern Office Hijab Selfie', 'A high-angle selfie of a {argument name="subject" default="young woman wearing a black hijab"}, posing casually inside a {argument name="setting" default="modern office environment"}. She is wearing round sunglasses with thin frames. Her facial expression shows a playful duck face (pout lips), giving a cute, slightly flirty and soft vibe.
Outfit: a {argument name="outfit" default="black jacket with a vintage logo patch on the front and a brown corduroy collar"}, paired with a finely pleated black skirt. She is holding a green matcha latte in a transparent plastic cup with a straw in her right hand.
Background: a realistic office setting such as a workspace or break area, featuring desks, office chairs, computers/laptops, and small items like files or stationery. The floor may be tiled or carpeted. Through the window, there’s a slightly wet, post-rain atmosphere outside, creating a fresh mood. Modern glass elements or office partitions are visible.
Composition: the image feels spontaneous, like a real phone selfie. The framing is slightly imperfect and natural, giving a candid, unposed look.
Lighting: a mix of soft natural light from the window and indoor white office lighting, balanced and not too harsh.
Focus: sharp focus on the face and outfit, with a shallow depth of field (slightly blurred background).
Style: ultra-realistic, candid selfie, iPhone camera look, natural lighting, high-detail skin texture, aesthetic daily life, slightly grainy, real-life vibe, 4K.', 'general', 'Kashberg');
INSERT INTO prompts (title, content, category, author) VALUES ('Profile / Avatar - Rome Balcony Selfie Lifestyle', '{ "type": "image_prompt", "version": "1.0", "description": { "subject": { "identity": "Use uploaded reference image, keep identity exact", "appearance": { "expression": "Confident composed expression with slightly pursed lips and direct gaze", "hair": "Use uploaded reference image, keep identity exact, hair with , smooth with slight natural volume", "accessories": [ "Thin silver necklace", "Drop earrings with light blue stones", "Minimal rings", "Slim bracelet" ], "details": [ "Defined brows and sharp eye makeup", "Glossy lips with natural tone", "Subtle skin highlights on cheekbones and shoulders", "Realistic skin texture without over-retouching" ] }, "body": { "type": "Slim feminine figure", "features": [ "Defined collarbones", "Slim arms", "Natural proportions" ] } }, "clothing": { "dress": { "type": "Elegant fitted evening dress", "color": "Light pink", "design": [ "Thin spaghetti straps", "Lace trim detail along neckline with a little sign ''Keor'' embroidered on border", "Slight sweetheart shape", "Smooth satin-like fabric with subtle sheen" ], "fit": "Body-hugging upper silhouette" } }, "pose": { "stance": "Standing on balcony taking selfie", "body_position": "Upper body angled slightly toward camera", "hands": "One arm extended holding selfie camera perspective, other hand gently placed near chin", "head_direction": "Slight tilt", "gaze": "Looking directly into camera" }, "environment": { "location": "Outdoor balcony in rome", "time": "Blue hour / early evening", "background": [ "Coliseum in backdrop", "City rooftops and parked cars below", "Soft gradient sky transitioning from blue to dusk tones", "Balcony railing" ], "atmosphere": "Calm evening with soft ambient light" }, "lighting": { "type": "Mixed natural and phone flash lighting", "style": "Flash-lit subject with soft ambient background", "effect": "Bright sharp illumination on face and upper body, slightly cooler tones in background, realistic contrast" }, "mood": [ "Modern", "Confident", "Evening lifestyle", "Minimal luxury" ], "technical": { "framing": "Close-up selfie framing", "camera_angle": "Slight high arm-length angle", "focal_length": "28mm equivalent", "style": "Photorealistic smartphone photography", "quality": [ "Sharp facial detail", "Natural color balance", "Slight background softness", "Realistic lighting contrast", "No over-saturation" ] } } }', 'general', 'Lipe');
INSERT INTO prompts (title, content, category, author) VALUES ('Profile / Avatar - Elegant Studio Portrait Prompt', 'Studio portrait of a {argument name="subject" default="woman with long wavy hair"}, {argument name="lighting" default="soft lighting"}, elegant styling, high-resolution, using reference face', 'general', '𝐊𝐢𝐧𝐳𝐚| 𝗔𝗜');
INSERT INTO prompts (title, content, category, author) VALUES ('Profile / Avatar - Intimate Feline Companion Portrait', 'Create an image features a close-up portrait of a young woman with dark hair and a nose ring, wearing a {argument name="clothing" default="teal and gold patterned headscarf"}. She has a gentle expression and is holding a {argument name="companion" default="fluffy, grey cat"} close to her face. The cat appears somewhat unimpressed or sleepy, with its amber eyes narrowed toward the camera. The photo has a nostalgic, film-like quality characterized by warm skin tones and a soft, slightly grainy texture. The background is simple and dark, which allows the focus to remain entirely on the bond between the woman and her feline companion. The overall composition feels intimate and candid, capturing a quiet, domestic moment. Without flower in hair please.', 'general', 'Ai Bella');
INSERT INTO prompts (title, content, category, author) VALUES ('Profile / Avatar - Striped Window Shadow Editorial', 'A hyper-photorealistic portrait of the same female subject, preserving exact face, skin tone, and proportions.

Scene:
Subject standing near a window with striped shadow patterns crossing her face, neck, and chest, wearing a {argument name="outfit" default="chiffon lace white button-up sleeveless"}, wind moving hair across her lips, dreamy editorial mood.

Camera settings:
Early-2000s CCD digital camera with direct flash softened by daylight, visible grain, slight color inconsistency, bright highlights on nose and lips, imperfect handheld framing. Portra 400 color rendering: warm creamy skin, pastel whites, muted saturation, gentle highlight roll-off layered over flash harshness, neutral-to-warm white balance.

Makeup:
Rosy complexion, dewy with visible pores, brushed-up feathery brows, thin wing eyeliner, wispy eyelashes, grey contact lenses, pink lip gloss.

Hair:
{argument name="hair style" default="Modern long layered style with inward upward curled ends"}, messy windswept motion, loose strands crossing the face, airy volume.

Negative prompt:
no overly clean studio photo, no plastic texture, no face blur, no heavy film filter.', 'general', 'Chryz leen');
INSERT INTO prompts (title, content, category, author) VALUES ('Profile / Avatar - Editorial CCD Close-up Beauty Portrait', 'Create image: A hyper-photorealistic close-up beauty portrait of the same female subject, preserving exact facial identity.

Scene:
Subject lying sideways with one hand framing her forehead and the other near her cheek, eyes looking upward, intimate soft editorial crop, visible fingers and natural hand anatomy.

Camera settings:
Shot on an early-2000s CCD digital camera, direct on-camera flash, harsh flash falloff, bright hotspot on face and upper chest, slightly overexposed highlights, visible digital grain, imperfect snapshot framing. Color rendering inspired by Kodak Portra 400: warm creamy skin tones, pastel softness, muted saturation, gentle highlight roll-off layered over flash harshness. Neutral-to-warm white balance.

Makeup:
Rosy complexion, dewy with visible pores, brushed-up feathery brows, thin wing eyeliner, wispy eyelashes, grey contact lenses, pink lip gloss.

Hair:
Modern messy windswept layered hair, inward upward curled ends, soft flyaways around the eyes, cheek, and lips.

Composition:
Extreme close-up, eyes and lips critically sharp, natural skin texture preserved, shallow softness around the edges.

Negative prompt:
no distorted fingers, no extra fingers, no plastic skin, no face change, no waxy makeup.', 'general', 'Chryz leen');
INSERT INTO prompts (title, content, category, author) VALUES ('Profile / Avatar - Moody Editorial CCD Digicam Portrait', 'Create image: A hyper-photorealistic close-up portrait of the same female subject, preserving exact facial identity, skin tone, and proportions.

