INSERT INTO prompts (title, content, category, author) VALUES ('Social Media Post - Pixel Art to Perler Bead Photo', 'Generate a photo of the finished {argument name="craft type" default="Perler bead creation"} based on {argument name="reference image" default="Figure 1"}', 'creative', '三重刘德华🔶BNB');
INSERT INTO prompts (title, content, category, author) VALUES ('Social Media Post - Lagos Street Candid iPhone Shot', 'Ultra-realistic zoomed iPhone back camera shot, slightly grainy.
Same woman walking on a {argument name="location" default="Lagos street"}.
Expression: unaware, natural walking face
Outfit: {argument name="outfit" default="simple fitted top + jeans"}, slightly wrinkled
Environment: roadside, okada/bikes blurred, cars in background, sunlight harsh
Camera style: taken from distance, slight digital zoom distortion, motion blur
Lighting: strong sunlight, deep shadows on face', 'general', 'Turnx');
INSERT INTO prompts (title, content, category, author) VALUES ('Social Media Post - High Angle Bed Selfie', 'A high-angle front-camera phone selfie of a young woman in her 20s sitting or half-lying on a {argument name="background" default="white bed"}. The camera is held slightly above her face, slightly offset to the right, looking downward in a close half-body composition where her face and upper body fill most of the frame. One eye is open and looking directly into the camera while the other eye is playfully winking. Her lips are slightly parted, giving a cute but slightly defiant and teasing expression. Preserve the small face, pointed chin, soft nose bridge, strong nose-tip highlight, delicate under-eye detail, and East Asian social-media selfie makeup style: pale luminous base, soft pink blush, slim natural brows, elongated eyeliner, glossy muted rose lips, and a tiny heart sticker or small cheek decoration. She has deep black long straight hair with airy bangs falling across the forehead, loose strands touching the cheeks, neck, and collarbones. The hair should look smooth and glossy but slightly messy, as if casually adjusted while on the bed. She wears a {argument name="clothing" default="black-and-white zebra-print low-cut thin-strap camisole"} with a gathered or twisted front detail; the fabric fits closely and the pattern bends along the body shape. Over it, she wears a {argument name="outerwear" default="medium-blue washed denim jacket"} slipping off the shoulders, with loose sleeves covering part of the arms. Visible skin includes the face, neck, collarbones, shoulders, upper chest, décolletage, arms, hands, small areas around the waist side, and upper thigh. The skin tone is fair with a cool pink undertone, appearing porcelain-bright under direct phone flash, with a smooth, soft, dewy, slightly glossy tactile quality. Strong small highlight patches appear on the nose bridge, collarbones, chest, and shoulders. One hand holds the phone while the other hand is close to the camera making a middle-finger gesture, creating mild wide-angle hand distortion. The background is a private bedroom bed scene with white pillows, wrinkled white bedding, a pink bunny plush toy, a brown animal cushion, and a warm gray-beige wall. Lighting comes mainly from close direct phone flash or strong frontal fill, while the room ambient light remains weak and soft; the white bedding bounces a little light back onto the skin. Keep the image realistic and casual, with phone-shot texture, slight beauty-filter smoothing, local flash highlights, messy hair strands, bedding wrinkles, plush toys, and an imperfect handheld composition. Avoid making it look like a polished commercial studio portrait.', 'general', 'Diamond');
INSERT INTO prompts (title, content, category, author) VALUES ('Social Media Post - Mixed-media collage portrait illustration', 'Create a high-detail {argument name="art style" default="contemporary mixed-media portrait illustration"} of a person attached in the uploaded reference image (
Do not change facial features of the person from the uploaded photo. Keep face of person 100% accurate from the reference image. Keep the original face of the attached person unchanged and realistic) in side-facing three-quarter profile, styled as a premium editorial art print / collage poster. Make it look like a real handcrafted screenprint–collage artwork scanned from paper — authentic print texture, halftone dots, paper grain, cut-paper layering, imperfect registration, and analog feel only. No AI-digital look.

The face is high-contrast black-and-off-white halftone/stipple (like old newspaper/photo-transfer), slender and elegant, calm serious expression, direct gaze, short dark hair with one soft curl over the forehead. A bold {argument name="eye band color" default="hot-pink/magenta"} horizontal eye band crosses both eyes (semi-opaque, eyes still visible beneath). Hair is a solid black cutout shape.

Layered collage fragments cut diagonally across the portrait: sky-blue cloud texture over forehead/cheek/jaw, lime-yellow geometric maze pattern on cheek/jaw, bold black-and-white diagonal stripes on the back silhouette, dark navy network scribble near the neck, beige torn-paper fragment, and lower neck/shoulder areas with overlapping warm orange, coral, peach, turquoise, and magenta textile patterns (zigzags, chevrons, diagonal stripes, mottled textures).

Vertical portrait composition, head dominant and slightly right of center, clean negative space, plain warm off-white paper background with subtle grain. Tiny artist-signature scribble in lower-right corner only.

Highly tactile, matte, scanned print aesthetic with visible paper tooth, ink absorption, and minor imperfections. Color palette: black, off-white/cream, hot pink/magenta, sky blue/cyan, lime yellow-green, dark navy, beige, orange/coral/peach, purple-magenta accents.

Editorial screenprint/risograph collage style — bold, graphic, refined, and physically real. Avoid photorealism, glossy gradients, 3D shading, smooth vectors, watercolor, text, or extra elements.
Aspect ratio {argument name="aspect ratio" default="4:5"}', 'general', 'Nano Banana Labs');
INSERT INTO prompts (title, content, category, author) VALUES ('Social Media Post - Ethereal Forest Twilight Portrait', 'A high-resolution cinematic portrait of a woman with {argument name="hair style" default="long wavy blonde hair"}, wearing a {argument name="hat style" default="wide-brimmed brown knit hat with a pearl trim"}. She has blue eyes and is wearing {argument name="lipstick" default="bold matte red lipstick"} and matching red almond-shaped nails. She wears a delicate gold necklace with a small turquoise pendant. The background is a soft-focus forest at twilight with golden bokeh. The lighting is soft and ethereal, emphasizing a sophisticated yet bohemian aesthetic.', 'general', 'Minahil');
INSERT INTO prompts (title, content, category, author) VALUES ('Social Media Post - Outdoor Baggy Fashion Portrait', 'Realistic full-body portrait of a slim young woman with the same reference face, standing confidently under a {argument name="natural element" default="blue-leaf tree"} next to a beige wall with a carpet on the ground. She has both hands in her pockets, looking straight at the camera with a gentle expression. Front view, wide distance shot. Messy tousled hair falling over her forehead, naturally fair skin, elegant and graceful mood. She wears an {argument name="clothing top" default="oversized blue baggy sweater"}, {argument name="clothing bottom" default="white baggy jeans"}, and red-white mixed sports shoes. Slim athletic physique, natural lighting consistent with the outdoor setting, highly detailed, photorealistic.', 'general', 'Calira');
