INSERT INTO prompts (title, content, category, author) VALUES ('Social Media Post - Candid Mall Ice Cream Kiosk Photo', 'natural handheld iPhone14 Pro photo of a {argument name="subject" default="woman buying a McDonald''s ice cream cone"} at a {argument name="setting" default="small kiosk inside a Brazilian shopping mall"}, wearing simple everyday casual clothes like shorts and a basic t-shirt, realistic kiosk setup with bright yellow and red branding, visible price sign showing "casquinha 1,99", {argument name="background" default="mall corridor with glossy floors and people walking in the background"}, close eye level perspective focusing on the hand receiving the ice cream cone, strong white shopping mall lighting with slight overexposure, subtle motion blur and natural grain, unfiltered colors and authentic candid moment', 'creative', 'Dr. Samia');
INSERT INTO prompts (title, content, category, author) VALUES ('Social Media Post - Candid Summer Car Interior Portrait', '{ "image_prompt_data": { "subject": { "demographics": "{argument name="subject demographics" default="Young woman"}", "hair": { "style": "As reference as image mode" }, "appearance": { "skin_tone": "Fair with warm sunlit undertones", "skin_detail": "Ultra-realistic skin texture with visible pores, natural highlights from direct sunlight, subtle redness on cheeks and nose, soft natural imperfections, slight sheen due to strong light exposure", "makeup": "Minimal natural makeup — soft blush, lightly defined brows, subtle lashes, natural pink lips with soft matte finish" }, "facial_expression": { "eyes": "Looking directly toward camera with slight squint due to bright sunlight", "eyelids": "Partially narrowed from strong light exposure", "eyebrows": "Relaxed with a very slight inward tension from brightness", "cheeks": "Softly lifted due to natural facial tension in sunlight", "lips": { "position": "Gently closed", "shape": "Subtle soft curve with a faint hint of a confident smirk", "tension": "Relaxed but slightly engaged" }, "jaw": "Relaxed and natural", "overall_expression": "Calm, confident, slightly sun-reactive expression with a relaxed, candid vibe" } }, "attire": { "top": { "type": "{argument name="clothing type" default="Sleeveless fitted top"}", "color": "White", "style": "Soft fabric with delicate trim detail", "fit": "Body-fitted, natural contour" }, "bottom": { "type": "Shorts", "color": "Dark tone", "fit": "Casual fitted" } }, "accessories": { "jewelry": "Minimal bracelet", "additional": "None" }, "environment": { "location": "{argument name="setting" default="Inside a car (front passenger seat)"}", "details": { "interior": "Dark car interior with dashboard and air vents visible", "objects": "Drink can placed near center console", "window": "Open car window allowing strong sunlight to enter", "atmosphere": "Casual candid summer moment" } }, "composition": { "type": "Candid lifestyle shot", "camera_angle": "Slightly above eye level, angled downward into car", "framing": "Mid-body framing including legs and upper torso", "pose": { "body_position": "Reclined sideways inside the car seat", "torso": "Leaning slightly back against seat", "legs": "Bent and positioned toward the camera, relaxed", "arms": "Resting naturally along body", "head": "Facing camera with slight tilt", "posture": "Relaxed, natural, candid lounging pose" } }, "lighting": { "type": "Natural harsh daylight", "source": "Direct sunlight entering from car window", "direction": "Side lighting hitting face and body " } } }', 'general', 'glena Jenner');
INSERT INTO prompts (title, content, category, author) VALUES ('Social Media Post - Indonesian Meme Style Prompts', '- meme image of {argument name="subject" default="a smiling cat"} with funny sentences in Indonesian

- meme image of {argument name="couple" default="a teenage couple"} sitting in a {argument name="location" default="restaurant/cafe"} with funny sentences in Indonesian/English', 'general', 'JefryBilang');
INSERT INTO prompts (title, content, category, author) VALUES ('Infographic / Edu Visual - Dreamy Studio Creative Illustration', 'A realistic, candid photograph of a {argument name="subject" default="petite Asian woman"} with a detailed, lifelike face and hairstyle (referencing the provided image for specific features), captured during a soft afternoon. She is wearing the specific clothing from the reference image. She is happily and intently hugging a {argument name="prop" default="gigantic wooden pencil"} adorned with cute, kawaii cartoon patterns with both hands, using it to draw on a massive sketchbook spread before her on a cozy room floor. The scene is full of warmth, with a soft, diffused sunlight filtering in. The floor is covered in pastel-colored (light pink, light blue) oversized toys, stationery, and a cute colored pencil box. A small, fluffy cat plush sits nearby. The room background features warm-toned wooden bookshelves filled with charming books and collectibles, all glowing with soft afternoon light. A minimal white doodle outline loosely traces the woman''s figure. Cute, minimal white handwritten text on the side reads "{argument name="text" default="Happy Monday"}", and pink handwritten text reads "Hello". Small, simple white doodle elements like stars, flowers, cats, and bunnies are scattered around. Four distinct, miniature 3D chibi-style figures, exact miniature replicas of the woman in the same clothing but in playful, mischievous poses, are placed around her on the shelves, books, and among the giant stationery. The entire image has a soft, dreamy, and warm glow, with pastel tones in the surroundings contrasting with natural wood and cream background colors. Shot on a Canon EOS R5 with a 35mm f/1.4 lens, natural grain, cinematic lighting. Aspect Ratio: 4:5 Style: Realistic Photo, Candid, Warm, Dreamy Lighting: Soft Afternoon Sunlight, Diffused', 'general', 'Aria');
INSERT INTO prompts (title, content, category, author) VALUES ('Infographic / Edu Visual - Fitness Journey Digital Collage', 'A vibrant, {argument name="theme" default="fitness-themed"} digital collage featuring a central photo of a {argument name="subject action" default="smiling woman jogging along a park path"}, surrounded by a series of expressive "chibi-style" stickers. The woman and her animated counterparts are dressed in matching {argument name="outfit colors" default="black and pink"} athletic gear. Each sticker depicts a stage of a workout journey—from the energy of a "Morning Run!" and the determination of a deep stretch, to the exhaustion of being "Almost There" and the final triumph of crossing a line. The composition is decorated with playful pink hearts, sparkles, and motivational text like "Just Do It!" and "Crushing Goals!", creating a cheerful and inspiring narrative.', 'general', 'Minahil');
INSERT INTO prompts (title, content, category, author) VALUES ('Infographic / Edu Visual - Luxury Cosmetic Brand Infographic', 'A professional cosmetic brand infographic in a soft aesthetic style. The color palette features {argument name="colors" default="muted rose, cream, and champagne gold"}. At the top center, a high-fashion portrait of a woman with glowing skin and soft makeup, wearing a {argument name="outfit" default="cream turtleneck"}. Below her, a clean grid of isolated makeup products: a glass foundation bottle with a liquid swatch, a sleek black mascara wand, and a rose-gold blush compact. The background is a clean, minimal gradient. Professional studio lighting, soft shadows, high-end commercial photography style, 8k resolution.', 'general', 'Minahil');
INSERT INTO prompts (title, content, category, author) VALUES ('Infographic / Edu Visual - Lilac Whimsical Self-Love Concept', 'A vibrant and whimsical conceptual image centered on a smiling young woman with {argument name="hair" default="blonde wavy hair"}, her eyes closed in a moment of serene joy as she cradles her face with both hands. She is set against a solid {argument name="background color" default="lilac"} background adorned with faint stars, hearts, and the word "LILAC" scattered throughout. The composition features several "miniature" versions of herself interacting with her and her surroundings, creating a surreal narrative of self-care and positivity.
​On her shoulders, tiny versions of her work together to stack hearts and style her hair, while another group walks across a floating purple ledge carrying glowing stars. To the right, miniature figures engage with a chalkboard that reads "{argument name="text" default="SELF-LOVE CLUB"}," and one sits nestled in the crook of her arm, admiring a small purple heart. At the bottom, a thought bubble containing the word "HAPPINESS" floats near another version of her waving cheerfully. The overall aesthetic is bright, playful, and heartwarming, utilizing a consistent palette of white, denim, and various shades of purple to emphasize themes of mental wellness and inner peace.', 'general', 'Minahil');
INSERT INTO prompts (title, content, category, author) VALUES ('Infographic / Edu Visual - Azuchi-Momoyama Castle Floor Plan', '{argument name="architecture" default="Azuchi-Momoyama style castle tower"} {argument name="drawing type" default="floor plan, blueprint, and area notation"}', 'general', 'Zero_Zero');
INSERT INTO prompts (title, content, category, author) VALUES ('Infographic / Edu Visual - Minimalist Personal Color Analysis Board', 'Design a square (1:1) aesthetic personal color analysis board in a {argument name="board style" default="soft beige, minimalist style"}.

Place a close-up portrait of a {argument name="subject" default="young woman"} at the center, featuring natural makeup and soft daylight lighting.

Add the title “Personal Color Analysis” above or beside the portrait.

Include a section labeled “Color Profile: {argument name="color profile" default="Soft Autumn (warm, muted, soft)"}”.

Display clean color swatches featuring warm neutrals, earthy tones, muted greens, soft blues, and terracotta shades.

Add a “Best Colors” grid along with an “Avoid Colors” grid highlighting overly bright or cool tones.

At the bottom, include 4–5 small images of the same woman styled in outfits that match the recommended palette.

Use a refined combination of elegant serif and minimal sans-serif fonts, soft shadows, and a clean editorial layout.

The background should be warm beige with a subtle texture.

Ensure the design feels spacious, polished, and Instagram-ready.', 'general', 'IQRA👑');
INSERT INTO prompts (title, content, category, author) VALUES ('Infographic / Edu Visual - Ancient Egyptian Profile Portrait', 'Ancient Egyptian profile portrait of the person in the reference image, side-facing pose (strict profile view), inspired by {argument name="style source" default="traditional tomb paintings"}, {argument name="features" default="almond-shaped eye, elongated eyeliner, sharp nose and chin"}, wearing a {argument name="headwear" default="nemes headdress"} and ornate gold jewelry, flat perspective, stylized proportions, warm sandstone and gold color palette, hieroglyphic background, smooth matte texture, soft even lighting, highly detailed, clean lines, 4k, museum-quality artwork', 'general', 'Shushant Lakhyani');
INSERT INTO prompts (title, content, category, author) VALUES ('Infographic / Edu Visual - Clean Whiteboard Animation Illustration', 'clean {argument name="style" default="whiteboard animation style"} illustration of the person from the reference image, drawn as a simple {argument name="medium" default="black marker sketch"} on a pure white background. Use bold hand-drawn outlines, minimal shading, and a slightly exaggerated cartoon-like style while still preserving the person’s recognizable facial features, hairstyle, and expression. Add subtle motion lines and sketch imperfections to mimic real hand-drawn animation. The character should appear as if being drawn on a whiteboard, with a casual, engaging, and educational vibe. Keep the composition minimal, high contrast, and visually clear, with no complex background elements', 'general', 'Shushant Lakhyani');
INSERT INTO prompts (title, content, category, author) VALUES ('Infographic / Edu Visual - Flower Mandala Coloring Page', 'A black and white line drawing of a {argument name="flower type" default="stylized flower"} with {argument name="pattern style" default="intricate patterns"} fills the frame. The flower''s center is an oval shape with smaller circles inside, surrounded by eight large petals. Each petal is decorated with parallel lines and some have a leaf-like shape. The background is a complex arrangement of geometric and organic patterns, including semicircles, zigzags, swirls, and a grid of dots. The overall composition is symmetrical, with the flower as the central focus, and the surrounding patterns radiating outwards.', 'general', 'Heather Green');
INSERT INTO prompts (title, content, category, author) VALUES ('Infographic / Edu Visual - High-Fashion Marketing Infographic', 'This high-fashion marketing infographic, titled {argument name="title" default="Elegance Defined"} by {argument name="brand" default="Vogue Vista"}, showcases a sophisticated bespoke collection of modern classic dresses. A central model poses in a {argument name="dress description" default="terracotta, tea-length, semi-fitted A-line dress featuring a boat neck and cap sleeves"}, set against a neutral, minimalist background. The layout includes a "Fit & Style Guide," a "Premium Attributes" section highlighting the luxurious crepe fabric and artisanal finish, and a {argument name="color collection" default=""Color Collection" featuring six shades like Seafoam Green and Midnight Plum"}. At the bottom, an "Occasion Pairing Guide" uses a series of lifestyle thumbnails to demonstrate the dress''s versatility for events ranging from garden parties and art openings to formal evening galas.', 'general', 'Minahil');
INSERT INTO prompts (title, content, category, author) VALUES ('Infographic / Edu Visual - Hair Care Product Infographic', '{
  "camera_settings": {
    "lens": "85mm f/1.8",
    "perspective": "Eye-level portrait",
