INSERT INTO prompts (title, content, category, author) VALUES ('Comic / Storyboard - Phoenician Sailor Portrait', 'realistic, cinematic portrait of the {argument name="subject" default="person from the reference image"} dressed in a traditional {argument name="attire" default="Phoenician sailor tunic"}. Preserve the person’s exact facial features, expression, and identity. Outfit them in an ancient Phoenician maritime look: a simple linen tunic with natural dyes (off-white, deep red, or indigo), a rope belt, subtle embroidery patterns, and weathered textures. Add period-accurate details like leather sandals, a headband or cloth wrap, and light sea-worn accessories. Set the scene near an {argument name="setting" default="ancient Mediterranean harbor"} with wooden ships, ropes, and soft golden sunlight. Use high detail, natural lighting, historical accuracy, and a cinematic, realistic style.', 'general', 'Shushant Lakhyani');
INSERT INTO prompts (title, content, category, author) VALUES ('Comic / Storyboard - Crayon Style Profile Transformation', 'Edit the provided image and reimagine the entire scene as a {argument name="style" default="crayon-style drawing"}. Simplify the details and make it look like it was drawn by a 10-year-old child. Do not use the original image’s colors. Give it the feeling of being drawn on a sheet of white paper, with a very cute, playful, and innocent look. Add charming childlike elements such as {argument name="elements" default="flowers, candy, stars, clouds"}, and other sweet decorative details to enhance the whimsical feel. Keep the overall result adorable, colorful, and full of childlike innocence.', 'general', 'Dr. Samia');
INSERT INTO prompts (title, content, category, author) VALUES ('Comic / Storyboard - Cross-Hatched Ink Portrait', 'A high-detail pen and ink portrait of a {argument name="subject" default="young woman with freckles"}. The style uses heavy cross-hatching and fine line work to create depth and shadow. Incorporate {argument name="hair style" default="messy, wind-swept hair"} with loose strands crossing the face. Background features soft, smudged charcoal washes and ink splatters. Black ink on a {argument name="paper texture" default="cream-colored textured paper or parchment"}. Sharp, intense gaze, monochromatic.', 'general', 'Minahil');
INSERT INTO prompts (title, content, category, author) VALUES ('Comic / Storyboard - Subway artist sketching perspective', 'Do not change facial features. Photorealistic first-person view inside a {argument name="location" default="bright subway car"}. In hand is a {argument name="drawing tool" default="spiral sketchbook with a pencil"}. On the sketchbook page is a {argument name="sketch style" default="black-and-white portrait sketch"} of the exact same person, where the only colored element is their clothing. Sitting opposite is this same person looking at a phone. Outside the window is a green landscape. On both sides, other passengers are partially visible, unblurred. Soft natural daylight, shallow depth of field, cinematic atmosphere. Hyperrealistic skin, detailed facial textures, natural expression. 8K photorealism quality. Aspect ratio 9:16.', 'general', 'Ai Prompts Lab');
INSERT INTO prompts (title, content, category, author) VALUES ('Comic / Storyboard - Cinematic police raid scene', 'ultra realistic photo, young woman with {argument name="subject appearance" default="pale skin and long black hair"}, same face as reference, emotionless expression, slightly tired eyes, standing with hands behind her back as if handcuffed, relaxed posture, slight head tilt, confident “I regret nothing” attitude

{argument name="location" default="luxury modern apartment at night, panoramic windows with city lights, expensive minimalistic interior"}, cinematic atmosphere

large wooden table in front of her covered with:
huge stacks of {argument name="currency" default="US dollars and euro banknotes"}, slightly messy but mostly organized,
black duffel bag filled with cash, partially open,
multiple smartphones (latest models),
2-3 laptops (MacBook style),
many bank cards spread in rows across the table

behind and around her:
tactical officers in black uniforms (special forces style), faces covered, actively searching the apartment,
some opening шкафы and shelves,
some walking in the background,
one officer standing near the table pointing at the money

cinematic lighting, soft cold light from windows mixed with warm interior light, realistic shadows, reflections on table

medium shot, slightly low angle, focus on the girl, shallow depth of field, background slightly blurred

dark luxury, tension, realistic raid scene, controlled chaos.', 'general', 'Dr. Samia');
INSERT INTO prompts (title, content, category, author) VALUES ('Comic / Storyboard - Rotoscoping animation style conversion', 'Rotoscoping style illustration of a {argument name="subject" default="real person"} based on the reference image, preserving exact facial features, pose, and expression, clean hand-drawn outlines, smooth vector-like shading, semi-realistic proportions, subtle color gradients, minimal but accurate background, cinematic lighting, high detail, crisp edges, animation frame aesthetic, inspired by {argument name="animation style" default="classic rotoscope animation techniques"}, 4k quality, sharp focus', 'general', 'Shushant Lakhyani');
INSERT INTO prompts (title, content, category, author) VALUES ('Comic / Storyboard - Multi-Panel Comic Illustration', '"{argument name="subject" default="Boy and dragon"} become friend, {argument name="style" default="american comic multi-panel illustration"}, diagonal layout, {argument name="panel count" default="six panels"}, cinematic storytelling, clear reading flow, with speech bubbles."', 'general', 'Nimentrix');
INSERT INTO prompts (title, content, category, author) VALUES ('Comic / Storyboard - Surreal Birch Bark Portrait Prompt', '{
  "vibe_title_en": "Bark''s Resistance",
  "master_prompt": "A hyper-realistic, medium format surreal portrait of {argument name="subject" default="The Protagonist"}. The subject features incredible practical-effect prosthetic makeup: their skin is cracking open down the neck and torso like dry, rough birch bark, revealing raw, fibrous wood underneath. Autumn leaves are organically intertwined into their hair. The subject stares directly into the camera with an unwavering, fierce ''Warrior''s Resolve'' and confrontational energy. Shot ''Through the Element'': the camera peers through out-of-focus, decaying autumn foliage in the extreme foreground, creating profound depth. The setting is a shattered, overgrown dark botanical greenhouse. Dramatic dual-color lighting: a piercing deep blue ambient moonlight clashes with an intense, striking crimson red rim light that highlights the physical weight and jagged edges of the bark prosthetics. Captured on a Hasselblad H6D-100c, 100mm f/1.8 lens. Analog texture, Cinestill 800T halation, visible skin pores blending flawlessly into wood grain, physical light refraction, profound cinematic tension. NO NEON.",
  "meta": {
    "intent": "Surreal high-fashion editorial",
    "priorities": "Surreal practical effects, dual lighting, intense gaze, foreground framing",
    "device_profile": "High-end cinematic photography"
  },
  "frame": {
    "aspect": "3:4",
    "composition": "Through the Element (foreground foliage), central subject alignment",
    "layout": "Medium close-up portrait",
    "camera_angle": "Eye-level, straight on",
    "tilt_roll_degrees": "0"
  },
  "subject": {
    "gender": "Female",
    "identity": "The Protagonist",
    "demographics": "Ageless surreal entity",
    "face": "Fierce, direct eye contact, warrior''s resolve",
    "hair": "Interwoven with dry autumn leaves",
    "body": "Skin cracking like birch bark, revealing fibrous wood inside the torso",
    "expression": "Confrontational, defiant, unwavering",
    "pose": "Standing firm, squaring shoulders to the lens"
  },
  "wardrobe_accessories": {
    "garments": [
      {
        "item": "Birch bark skin integration (prosthetic surrealism)",
        "material": "Wood and human skin",
        "color": "White, brown, dark fissures",
        "fit": "Body-mod"
      }
    ],
    "accessories": [
      {
        "item": "Autumn leaves crown",
        "color": "Golden, rust orange",
        "material": "Organic dried leaves",
        "brand_style": "Avant-garde nature"
      }
    ]
  },
  "environment": {
    "setting": "Shattered, overgrown botanical glasshouse",
    "surfaces": "Cracked glass, creeping vines, dry earth",
    "depth": "Shallow depth of field with heavy foreground occlusion",
    "atmosphere": "Tense, cold ambient with harsh aggressive localized heat",
    "lens_interaction": "Shooting through out-of-focus foreground leaves"
  },
  "lighting": {
    "key": "Deep blue ambient (moonlight)",
    "fill": "Soft cool shadow"
}', 'general', 'timedoctor.eth');
INSERT INTO prompts (title, content, category, author) VALUES ('Comic / Storyboard - Neo Goku in the Machine City', '{argument name="character" default="Neo Goku"} - Arrives at the {argument name="location" default="city of machines"}', 'general', 'Universo IA ( Skynet )');
INSERT INTO prompts (title, content, category, author) VALUES ('Product Marketing - CNC Router Wood Sculpture Simulation', 'cmd>> initiate 5-axis cnc router simulation

target_material: high-density mdf and pale balsa wood blocks, glued in visible horizontal strata (layers).
milling_subject: [variable_location]
[variable_location]: "{argument name="location" default="city mecca"}"

toolpath_instructions:
1. roughing_pass: carve the master block into an impossible, continuous mobius-strip geometry.
2. finishing_pass: micro-carve the surface to perfectly replicate the urban layout of [variable_location]. 
3. ai_detailing: the router must intricately carve the buildings, monuments, houses and other elements of the [variable_location[, seamlessly bending them along the twisted wooden loop. 

surface_finish: 
do not paint. leave the laser-burn marks in the deep crevices. leave the wood dust in the tiny carved streets. insert microscopic silver metal pins to represent cars on the looping avenues.

render_output:
a photorealistic close-up of this finished physical sculpture resting on a craftsman''s workbench. overhead shop lighting.', 'general', 'Gadgetify');
INSERT INTO prompts (title, content, category, author) VALUES ('Product Marketing - Raw Mixed-Media Street Art Poster', 'Create a high-detail mixed-media editorial poster of a person ( Keep the face of the person 100% accurate from the reference image ) in a left-facing side profile. It should look like a real printed poster, not digital—use paper grain, ink texture, halftone, and slight scan imperfections.

Portrait in matte black tones with realistic skin detail, not flat. Short twisted locs on top, faded sides, trimmed beard. Add white hand-drawn outlines on some hair strands.

Include a hoop earring with a cross pendant and a thin chain with a cross. Expression calm and serious.

Add white hand-drawn dots, lines, and abstract symbols across the face, neck, and shoulders, like chalk or marker on a printed photo.

Background: {argument name="background color" default="vivid yellow"} with black graffiti-style doodles (crowns, eyes, stars, abstract shapes). Add subtle olive/gold accents.

Top text: {argument name="text" default="smack"} in bold black sans-serif.

Composition: vertical poster, head and shoulders, slightly left-centered, facing left.

Colors: yellow, black, white, small olive accents.

Style: raw, street-art, zine-like, real printed poster feel. No glossy or 3D look. Avoid smooth digital finish or AI artifacts.

Aspect ratio 4:5', 'general', 'Nano Banana Labs');
INSERT INTO prompts (title, content, category, author) VALUES ('Product Marketing - Arabian Desert Luxury Product Shot', 'A cinematic, ultra-detailed scene set in a vast Arabian desert at night under a deep indigo sky filled with stars and a glowing crescent moon. A beautiful Middle Eastern woman stands gracefully on soft golden dunes, wearing a {argument name="attire" default="traditional vintage Arabian dress inspired by old Bedouin culture, flowing black and gold abaya with intricate embroidery"}, delicate veil partially covering her face, adorned with antique gold jewelry and subtle gemstones. She holds an elegant, {argument name="bottle design" default="luxurious juice bottle designed like a classic oud perfume flacon"}, made of dark amber glass with ornate gold carvings, a decorative cap, and intricate Arabic patterns glowing subtly under soft moonlight. The bottle looks premium, rare, and culturally rich. She gently drinks from the bottle, her expression calm and regal, the fabric of her dress flowing softly with the desert breeze. Lanterns placed around cast warm golden light, contrasting with the cool moonlight, creating a dramatic high-end advertisement aesthetic. Ultra-realistic, 8K resolution, sharp focus, soft depth of field, cinematic lighting, luxury product photography style, rich textures, high contrast, elegant composition, no modern elements, timeless Arabian atmosphere.', 'general', 'Snow');
INSERT INTO prompts (title, content, category, author) VALUES ('Product Marketing - Cyberpunk Streetwear Editorial', 'Hyperrealistic 4K HDR fashion editorial photo of a young man with black-framed glasses, wearing a {argument name="hoodie" default="dark forest green oversized hoodie"}, a dark beanie hat, wide-leg baggy pants, and classic canvas sneakers — standing next to an {argument name="companion" default="anthropomorphic cartoon duck character"} dressed in a {argument name="jacket" default="gold bomber jacket"}, black joggers, gold chain medallion, and yellow high-top sneakers. Both striking a bold, arrogant, confident street-style pose. Urban environment with vibrant graffiti-covered concrete walls, spray-painted tags and throw-ups, neon orange and yellow dripping lettering, Japanese kanji murals splashed across the background. Boombox sitting on the ground beside them. Saturated punchy colors — electric yellow, deep forest green, neon orange, bold red accents. Graffiti text tags: "RAP", "MUSIC", "ART INFINITY", "OVA10", "EXIT", "HRN". Street fashion photography aesthetic mixed with urban illustration. Cinematic dramatic lighting, deep shadows, rim light. Ultra-sharp 4K HDR details, photorealistic textures, high contrast, fashion magazine quality shot.', 'general', 'Harboris');
INSERT INTO prompts (title, content, category, author) VALUES ('Product Marketing - Surreal Fried Chicken Commercial', 'A surreal, high-end studio advertisement featuring an oversized crispy fried chicken bucket inspired by KFC, placed on a clean reflective surface. The bucket is filled with golden, crunchy fried chicken pieces with rich texture and visible seasoning flakes. Background is a smooth pastel red gradient with soft diffused lighting and subtle reflections.

A {argument name="subject" default="young man"} (use my face) stands confidently beside the giant chicken bucket, leaning casually against it. He wears a {argument name="outfit" default="clean white athleisure outfit"}, minimal and stylish, creating contrast with the warm tones of the chicken. He holds a single crispy drumstick in his hand, eyes closed with a satisfied expression, enjoying the aroma.

Composition is centered, ultra-sharp, cinematic lighting, premium commercial photography style, shallow depth of field, hyper-realistic textures, 8K quality.

Large bold typography in the background: “KFC STYLE” (or replace with your brand name if needed).
Tagline at bottom: “{argument name="tagline" default="Crispy joy, every bite."}”', 'general', 'Snow');
INSERT INTO prompts (title, content, category, author) VALUES ('Product Marketing - Macro Food Advertisement Photography', 'Ultra-realistic {argument name="food type" default="food with juicy / melting / dynamic details"}, dark background, dramatic lighting, macro shot, shot on Nikon D850, 100mm macro lens, f/2.8, ultra detailed textures, food advertisement style', 'creative', 'Calira');
INSERT INTO prompts (title, content, category, author) VALUES ('Product Marketing - Surreal Luxury Handbag Editorial', 'A surreal, ultra-premium studio product scene featuring a {argument name="product" default="pair of oversized deep burgundy leather luxury handbags"} placed diagonally on a polished reflective surface. The bags are crafted with smooth Italian leather, gold-plated hardware, embossed monogram patterns, and subtle stitching details, giving a high-fashion couture aesthetic.

The background is a {argument name="background" default="rich gradient of dark plum fading into warm champagne gold"}, with soft cinematic lighting creating a luxurious glow and refined shadows.

Three miniature women interact with the oversized handbags, enhancing the surreal scale contrast. All women wear elevated fashion looks (tailored black blazers, silk tops, fitted trousers) with statement sunglasses, styled in tones of burgundy, gold, and black to complement the product.

One woman stands on the left adjusting a sleek golden chain attached to the handbag, grounded and composed. Another woman is suspended mid-air holding onto the chain strap, leaning playfully against the bag’s curved surface. The third woman stands confidently on the right atop the base of the bag, posing with elegance and authority.

The chain strap flows across the composition in a soft curve, guiding the viewer’s eye and adding motion.

Composition is cinematic and balanced, with generous negative space in the upper frame. Focus is razor sharp on the handbag textures, with a shallow depth of field softly blurring the background.

Style: ultra-realistic, luxury editorial campaign, surreal scale, high-fashion product photography
Camera: {argument name="camera" default="85mm lens"}, eye-level angle, shallow depth of field
Lighting: soft diffused studio lighting with warm highlights, subtle reflections on leather and metal
Aspect ratio: 9:13 vertical', 'general', 'Snow');
INSERT INTO prompts (title, content, category, author) VALUES ('Product Marketing - Surreal Giant Shoe Sports Advertisement', 'Creative surreal photography featuring a sporty person (based on the uploaded subject photo) wearing a {argument name="outfit color" default="black athletic outfit"} (sportswear such as tank top, shorts/leggings, and optional cap), sitting on a concrete riverside walkway. The subject’s identity (face, body, hairstyle) must closely match the uploaded photo, adapted naturally into a sporty look.

The subject is leaning against a giant oversized version of the exact shoe from the uploaded shoe image, scaled dramatically larger than the subject. The shoe must accurately preserve all original details, including colors, textures, branding, and materials.

Shot using forced perspective, making the shoe in the foreground appear massive and dominant. 

In the background, a white fence, river, and modern city skyline are visible under a bright blue sky with light clouds.

On the left side, a digital overlay UI displaying running statistics in English, including a bold number like “{argument name="statistic" default="10.04"}”, along with distance, pace, time, and other fitness metrics in a clean, modern layout.

Lighting: bright daylight, natural sunlight highlighting textures of the mesh shoe and athletic outfit.

Mood: energetic, modern, sporty lifestyle advertisement.
Color tone: vibrant and clean, maintaining realistic colors from both subject and shoe.

Detail: ultra-realistic, high detail, sharp focus, 8K resolution, professional photography.', 'general', 'วิ่งให้เป็นขนม🏃🏼‍♂️🚲💪🏾');
