INSERT INTO prompts (title, content, category, author) VALUES ('Product Marketing - Commercial Beverage Advertisement Scene', 'A beautiful young South Asian woman with long, wavy dark brown hair, fair skin, and a radiant smile, wearing a stylish white pleated blouse with ruffled collar and sleeves, sitting at a modern glass table. She is holding a glass of red wine in her right hand, looking confidently to the side. 

In the foreground on the table is a {argument name="product name" default="Nestlé Fruita Vitals Gold Range "Red Grapes" juice"} bottle with golden cap and grape imagery. 

Background features a bright, luxurious modern interior with a large geometric glass dome ceiling and natural daylight streaming in. 

Top left corner has the Nestlé Fruita Vitals Gold Range logo. Large bold maroon text in the upper right says "{argument name="slogan" default="A SIP MEANS THE WORLD!"}". 

Professional commercial photography style, vibrant colors, sharp details, bright and airy atmosphere, advertising campaign aesthetic.', 'general', 'Jahan Zaib');
INSERT INTO prompts (title, content, category, author) VALUES ('Product Marketing - Elegant Garden Fashion Editorial', 'Create elegant woman walking outdoors in a {argument name="clothing" default="sparkling top and light trousers"}, confident stride. Style: fashion editorial photography, ultra-realistic, cinematic outdoor look. Camera: 50mm lens, full-body shot, natural depth. Action: walking forward with flowing shrug, strong gaze. Outfit: sequined top, sheer long shrug, light trousers, subtle accessories. Lighting: natural sunlight with soft highlights and background bokeh. Location: {argument name="location" default="garden pathway with brick wall and greenery"}.', 'general', 'ayzalnoor');
INSERT INTO prompts (title, content, category, author) VALUES ('Product Marketing - Yohji Yamamoto Style Editorial Portrait', 'Ultra-realistic fashion editorial portrait photography, a {argument name="hair color" default="platinum blonde"} short-haired {argument name="person" default="young woman"} in a dynamic pose, half-kneeling against a slanted surface, using a Dutch angle composition to create avant-garde visual tension. Platinum-white shoulder-length short hair with slightly flipped ends, dark almond eyes, fair and delicate skin, and a cold, detached expression with a high-end feel. Wearing a {argument name="top" default="white ribbed off-the-shoulder long-sleeved cropped top"} with a sheer fabric and knitted texture, paired with high-waisted bright red tight mini shorts, opaque white over-the-knee stockings, and red patent leather stiletto heels with clear mirror reflections on the surface. Soft diffused studio lighting comes from the upper right, forming delicate gradient shadows on the waist and jawline, with exquisite highlight reflections visible on the patent leather shoes. Minimalist gray-beige studio background, clean and pure without clutter. The overall color scheme consists of white, red, and gray, forming a high-contrast minimalist and harmonious palette. Medium format camera texture, shallow depth of field blur, high-resolution skin texture and fabric details, and an overall avant-garde, sophisticated, and high-fashion editorial vibe.', 'general', '三重刘德华🔶BNB');
INSERT INTO prompts (title, content, category, author) VALUES ('Product Marketing - Editorial Magazine Cover Design', 'An editorial magazine cover for ''{argument name="magazine title" default="Imaginary AURA"}'', featuring a confident {argument name="ethnicity" default="South Asian"} woman as the central figure. She has flowing, wavy dark hair and is wearing a rich emerald-green velvet blazer over a matching silk turtleneck.
​Her look is completed with striking chunky gold hoop earrings and a heavy, layered gold chain link necklace. She has a strong, powerful expression, directly engaging the viewer with her warm, makeup-enhanced brown eyes.
​The background features a warm, sandy desert landscape at twilight. A vertical headline in a stylish gold font reads, ''VISIONARIES: THE CREATIVE CANVAS,'' on the left. The bottom right features the text, ''DESERT BLOSSOM: Finding New Forms,'' with the sub-headline ''A Journey Through Textures and Light.''
​This captivating cover captures the essence of artistic exploration and the beauty found within diverse cultural contexts.', 'general', 'Minahil');
INSERT INTO prompts (title, content, category, author) VALUES ('Product Marketing - High-Energy Energy Drink Advertisement', 'This high-energy advertisement features a dynamic composition centered on a powerful female athlete in mid-leap, celebrating with a triumphant fist pump. She is dressed in neon green and dark forest green athletic wear that mirrors the branding of the "{argument name="brand name" default="Powey"}" energy drink. A large, tilted energy drink can dominates the midground, erupting with a dramatic splash of {argument name="liquid color" default="golden"} liquid, while crackling yellow lightning bolts surge around the subject to symbolize explosive energy. The background is a deep gradient green with the word "power" repeated in bold, oversized lime-green typography. The overall aesthetic is cinematic and high-contrast, utilizing a professional studio setup with a reflective dark floor and glowing neon accents. At the bottom, a smaller, upright can sits next to the bold sans-serif tagline "FUEL YOUR UNSTOPPABLE," grounding the vibrant, action-oriented scene.', 'general', 'Minahil');
INSERT INTO prompts (title, content, category, author) VALUES ('Product Marketing - Luxury Skincare Product Photography', 'High-resolution product photography for a luxurious skincare collection by "{argument name="brand name" default="AM COSMETICS"}." The "{argument name="collection name" default="Amethyst Collection"}" set, including a pump bottle, a dropper bottle, and a jar in {argument name="material" default="purple-tinted glass"} with rose gold accents, is presented on a natural amethyst geode platform. This platform rests on a moss-covered island in a calm mountain lake at twilight. Natural plants and small leaves adorn the island. One side of the frame features an elegantly styled woman with retro Hollywood wave hair, wearing a flowing, floor-length silk gown in antique pink, gently gesturing towards the products. The background is a serene vista of misty blue mountains and a peach-pink sunset sky. Elegant serif text at the top reads "Elevate Your Ritual" and "EXPERIENCE AMETHYST." Clean, diffused studio-quality lighting.', 'creative', 'Minahil');
INSERT INTO prompts (title, content, category, author) VALUES ('E-commerce Main Image - Studio Fashion Portrait with Abstract Pattern', '{ “image_description”: “A medium shot three-quarter back view photograph of a young woman with long, wavy blonde hair. She is turning to look over her shoulder. She is wearing a matching abstract patterned two-piece set, consisting of a tie-back crop top and a mini skirt with a high side slit. She holds a black bag with a silver chain. The background is a plain white studio setting.”, “subject”: { “gender”: “Female”, “appearance”: “Young woman with light skin and voluminous, wavy {argument name="hair color" default="blonde"} hair falling down her back.”, “pose”: “Three-quarter back view, turning slightly to her left and looking back over her left shoulder towards the camera. Her left arm holds a black bag, her right arm is bent near her body.”, “expression”: “A side-glance expression looking towards the viewer.” }, “clothing”: { “outfit”: “{argument name="outfit" default="Matching two-piece set"}.”, “top”: “Red and orange multi-color abstract patterned tie-back crop top with thin straps.”, “skirt”: “Matching mini skirt with a prominent, high slit on the left side (visible from the side/back view).”, “pattern_details”: “Abstract, irregular print pattern using red, orange, navy blue, and black accents.” }, “accessories”: { “bag”: “A black shoulder bag made of soft leather-like material, with a chunky silver chain strap, held in her left hand and slung over her left shoulder.”, “jewelry”: “A delicate silver chain bracelet on her right wrist.” }, “setting”: { “environment”: “Inside a professional photography studio.”, “background”: “{argument name="background" default="Solid, seamless white background"}.”, “flooring”: “Light gray or white textured studio floor, slightly out of focus.” }, “composition”: { “shot_type”: “Medium shot.”, “angle”: “Eye level, slightly behind and to the side of the subject.”, “framing”: “Focuses on the subject from the head to just above the ankles, highlighting the back detailing and the skirt slit.” }, “lighting”: { “type”: “Bright, even studio lighting, casting subtle shadows to define form.” } }', 'creative', 'Lore');
INSERT INTO prompts (title, content, category, author) VALUES ('E-commerce Main Image - Cozy English Cottage Interior with Laptop', 'Hyper-realistic vertical photograph 4:5. A cozy living room in an {argument name="interior style" default="English cottage"} featuring a {argument name="sofa color" default="cocoa-colored"} velvet sofa, parquet flooring, and antique furniture.
A young woman is sitting deeply relaxed in the sofa with her legs resting on a striped ottoman. On her lap is an open 16-inch Space Black MacBook Pro.
The laptop is the central focal point of the frame, creating a striking contrast between modern matte technology and the vintage interior.
Camera angle: high side view from the doorway.
Clothing: {argument name="outfit" default="Heavyweight oversized white t-shirt made of thick cotton, wide sage green corduroy trousers, white cotton socks, classic blue NY Yankees baseball cap worn casually"}, thin silver chain with a small medallion.
Lighting: Soft warm afternoon light coming through a large window on the left (out of frame), warm beige reflected light, and a golden highlight from a candle on the side table. No harsh shadows. Warm monochromatic color palette — cocoa, beige, cream, and sage.
Camera: Sony A7R V, 50mm f/1.4 lens, 8K sharpness, natural skin and fabric textures, natural depth of field. No plastic look, no CGI, no AI artifacts.', 'creative', 'Dr. Samia');
INSERT INTO prompts (title, content, category, author) VALUES ('E-commerce Main Image - Ultra-Realistic Boutique Mirror Selfie', '{
  "image_generation_prompt": {
    "goal": "Ultra-realistic smartphone mirror selfie of a {argument name="subject" default="female fashion store owner"} showcasing her {argument name="outfit description" default="outfit"}, indistinguishable from a real Instagram post.",
    "identity_consistency": {
      "priority": "critical",
      "reference": "Use uploaded image as absolute truth",
      "match": [
        "face (100% identical)",
        "body type & proportions",
        "skin tone & texture (pores, imperfections)",
        "hair (color, density, natural strands)"
      ],
      "rules": [
        "No stylization or modification",
        "Same person, not a generic model"
      ]
    },
    "outfit_accuracy": {
      "priority": "extreme",
      "reference_required": true,
      "match": [
        "fabric, folds, stitching, fit",
        "wrinkles, tension",
        "colors (exact)",
        "layering & proportions"
      ],
      "behavior": "Natural wear with realistic gravity and body interaction",
      "rules": [
        "Do not redesign, simplify, or improve",
        "Exact recreation (virtual fitting)"
      ]
    },
    "environment": {
      "type": "{argument name="environment" default="realistic boutique store"}",
      "elements": ["mirrors", "clothing racks", "decor"],
      "lighting": "soft, slightly warm retail lighting",
      "depth": "realistic spatial depth"
    },
    "scene": {
      "action": [
        "holding smartphone",
        "taking mirror selfie",
        "looking at phone screen"
      ],
      "pose": "natural, relaxed, confident, slight hip shift",
      "energy": "fashion entrepreneur"
    },
    "camera": {
      "type": "smartphone",
      "aspect_ratio": "5:7 vertical",
      "framing": "mid to full body",
      "features": [
        "slight perspective distortion",
        "accurate mirror alignment"
      ]
    },
    "lighting_realism": {
      "style": "natural store lighting, soft shadows, warm tone",
      "restrictions": ["no studio lighting", "no over-lighting"],
      "skin": "visible pores, micro-imperfections, subtle shine, no airbrushing"
    },
    "realism_details": {
      "clothing": "visible texture, natural folds & pressure",
      "mirror": "accurate reflections (phone, arms, depth)",
      "hands": "anatomically correct, natural grip",
      "imperfections": [
        "slight noise",
        "minor lighting inconsistencies",
        "depth falloff"
      ]
    },
    "visual_style": {
      "aesthetic": "instagram fashion",
      "color": "natural grading, no HDR",
      "avoid": [
        "CGI look",
        "over-sharpening",
        "artificial smoothness"
      ]
    },
    "final_expectation": "Feels like a real boutique owner casually posting a mirror selfie in her store."
  }
}', 'creative', 'sammy');
INSERT INTO prompts (title, content, category, author) VALUES ('E-commerce Main Image - Vintage European Scooter Ride', 'A cinematic lifestyle shot of a well-dressed man riding a vintage cream-colored scooter through a {argument name="location" default="historic European street"}. He wears {argument name="clothing" default="a tailored black suit, white shirt, and black tie"}, with polished dress shoes, giving a confident and elegant look. The setting features old stone buildings, a cobblestone road, and a classic fountain, with a grand cathedral softly blurred in the background. {argument name="lighting" default="Golden hour lighting"} casts warm tones and soft shadows, creating a timeless, romantic atmosphere. Slight motion blur on the surroundings, shallow depth of field, 50mm lens, f/1.8, ultra-realistic detail, luxury travel aesthetic, editorial fashion photography, 8K.', 'creative', 'Taaruk');
INSERT INTO prompts (title, content, category, author) VALUES ('E-commerce Main Image - Organic Skincare Product Advertisement', 'nature inspired atmospheric organicism: A nature-inspired atmospheric product advertisement for "{argument name="brand name" default="VERDANA Organic Baby Skincare"}". A small amber glass bottle and a matching cream jar rest beautifully nestled inside a bed of {argument name="botanical elements" default="fresh green sage leaves, sprigs of dried purple lavender, and draped soft white linen cloth"}, all placed on a warm, sunlit rustic wooden surface. The background is in soft-focus with a shallow depth of field, featuring blurred terracotta wall textures accented with climbing ivy. Hand-drawn, illustrative typography reading exactly "{argument name="slogan" default="GROWN FROM THE EARTH"}" floats gently above the products in slightly imperfect, organic, elegant letterforms. The overall color palette is muted and earthy, heavily featuring sage green, terracotta, warm ochre, and slate cream. Broad natural window lighting creates a soft, honest, and evenly diffused illumination across the scene. The image features a subtle chalk and watercolor paper texture overlay, offering an open, airy composition with generous negative space, evoking a deep sense of warmth, purity, and calm. Moderately high artistic stylization. 4:5 Aspect Ratio.', 'creative', 'Ashish Sheth');
INSERT INTO prompts (title, content, category, author) VALUES ('E-commerce Main Image - Luxury Cosmetic Product Shot', 'Premium cosmetic product shot of a {argument name="product" default="red glass dropper serum bottle"} emerging from a dramatic water splash ring, surrounded by floating {argument name="fruit" default="ripe strawberries"} and water droplets frozen in motion, reflective wet {argument name="color" default="pink"} surface, pastel pink background, bright studio lighting, high-speed photography look, hyper-realistic texture, luxury skincare advertisement, macro product photography, cinematic lighting, 8k, depth of field.', 'creative', 'Snow');
INSERT INTO prompts (title, content, category, author) VALUES ('E-commerce Main Image - Cartoon Cat Group T-Shirt Mockup', 'Ultra-realistic top-down product photography of a neatly folded V-neck t-shirt placed on a light wooden surface. The t-shirt is pastel teal/washed aqua color with a soft fabric texture and subtle faded shading. On the front print: a group of 8 highly detailed, stylized cartoon-realistic cats arranged closely together, facing forward. Each cat has exaggerated, expressive facial features — big glossy eyes, wide pupils, quirky crossed eyes, and playful goofy expressions. Several cats have their tongues sticking out in different directions, creating a humorous and chaotic vibe. Cat details: Mixed fur colors: ginger/orange tabby, cream, beige, light brown, and grey tones Soft, fluffy fur with hyper-detailed strands Rounded faces, small noses, and slightly chubby cheeks Variety of expressions: surprised, confused, silly, excited One or two cats looking slightly cross-eyed High emotional exaggeration, almost Pixar-style but more detailed Composition: Cats tightly grouped in a triangular cluster filling the chest print area Bottom row slightly cropped by shirt fold for realism Balanced spacing with layered depth (front and back rows) Lighting: Soft diffused studio lighting Gentle shadows under the folds and around the print Even illumination, no harsh contrast Style: Hyper-realistic + stylized 3D illustration blend High resolution, crisp details, professional product mockup Clean background, minimalistic aesthetic Camera: Top-down flat lay shot Slight perspective depth but mostly symmetrical Quality tags: 8K, ultra-detailed, sharp focus, photorealistic fabric texture, professional e-commerce product shot.', 'creative', 'Cherry 2.O');
INSERT INTO prompts (title, content, category, author) VALUES ('E-commerce Main Image - Photorealistic Car Transformation', 'turn this into a photorealism of a {argument name="car type" default="clean car"}, make all decals and stickers on the car real and meaningful, car on a {argument name="background" default="white background"}', 'creative', 'Olivio Sarikas');
INSERT INTO prompts (title, content, category, author) VALUES ('E-commerce Main Image - Explosive Dragon Fruit Juice Photography', 'In mid-air, a {argument name="fruit" default="dragon fruit"} splits explosively, scattering vibrant magenta pulp and tiny black seeds, with a "{argument name="brand" default="Minute Maid Dragon Fruit Juice"}" bottle blasting out from the core. Styled as hyperrealistic product photography, Sony A7s clarity, sharp HD. Background is {argument name="background color" default="neon pink-magenta"}.', 'creative', '𝐌');
INSERT INTO prompts (title, content, category, author) VALUES ('E-commerce Main Image - Luxury Chronograph Macro Design', '"{argument name="subject" default="Chronograph"} with {argument name="strap" default="leather strap"}. Studio macro, overhead spotlight, escapement close-up. {argument name="background" default="Dark matte background"}. Shallow depth of field. Photorealistic."', 'creative', 'SRKDAN');
INSERT INTO prompts (title, content, category, author) VALUES ('E-commerce Main Image - Citrus Product Photography', 'A {argument name=\"bottle color\" default=\"bright yellow-orange\"} bottle with a white pump stands on a matte podium, surrounded by thick creamy foam and {argument name=\"particles\" default=\"citrus zest particles\"}. The background is a gradient of sunny yellow with fresh bubble details. The label highlights organic citrus extracts and energizing freshness. {argument name=\"accents\" default=\"Lemon and orange slices\"} accentuate the vibrant appeal.', 'creative', '𝐌');
INSERT INTO prompts (title, content, category, author) VALUES ('E-commerce Main Image - Editorial Macro Mug Design', '{argument name="product" default="Ceramic mug"}, side lit, {argument name="atmosphere" default="steam rising"}, {argument name="surface" default="dark linen surface"}, editorial macro, no text, photorealistic', 'creative', 'SRKDAN');
INSERT INTO prompts (title, content, category, author) VALUES ('E-commerce Main Image - Skincare product advertisement with watermelon and bubbles', 'A vibrant premium skincare product advertisement featuring a glossy pink pump bottle placed at the center inside a round pastel pink bowl filled with rich white foam bubbles. Surrounding the bottle are fresh juicy watermelon slices arranged symmetrically, with visible texture and seeds. The background is a clean split-color pastel gradient soft pink on one side and mint green on the other creating a fresh summer aesthetic. 

Transparent floating soap bubbles fill the air, reflecting light with subtle rainbow highlights. Soft studio lighting with high-key brightness, smooth shadows, and glossy reflections on the bottle surface. Ultra-realistic textures, detailed foam, fresh fruit moisture, commercial advertising style, cinematic composition, sharp focus, 8k resolution, depth of field, clean minimal setup, vibrant color grading.', 'creative', '𝐌');
INSERT INTO prompts (title, content, category, author) VALUES ('E-commerce Main Image - Knolling Style Flat-Lay Prompt with Labeled Disassembled Parts', 'Ultra-realistic 8K overhead product photograph in precise knolling composition, straight top-down 90-degree view of the object from the provided reference image completely taken apart into {argument name="number of components" default="8 to 12"} essential components, each piece arranged with exact spacing in a disciplined grid or balanced radial layout on a minimalist matte gray or natural wood tabletop, flawless alignment, zero overlap, no unrelated props, soft diffused multi-light setup with gentle controlled shadows, neutral true-to-life color, edge-to-edge sharpness, highly authentic material rendering including brushed metal, molded plastic, rubberized grips, exposed circuit boards, screws and small hardware, every component outlined with a thin white rectangular frame and paired with a concise English sans-serif label placed adjacent to the part without obscuring it, annotations crisp, readable, understated, technical editorial aesthetic, no watermark, no logo, no clutter', 'creative', 'Tischeins');
INSERT INTO prompts (title, content, category, author) VALUES ('E-commerce Main Image - High-Quality Photo of Elegant Chinese Woman in Luxury Car', 'A high-quality photographic image featuring an elegant, young Chinese woman with a refined appearance, seated in the driver''s seat of a silver-gray luxury sedan.

She is wearing a {argument name="attire" default="pale yellow silk jumpsuit dress"} and looking at the camera with a gentle smile.

The car door is wide open, and her slender legs are extended outside, wearing a pair of {argument name="shoes" default="exquisite silver strappy high-heeled sandals"}.

The car interior shows a contrast of bright orange and deep black, equipped with a modern digital dashboard and steering wheel.

The background is a brightly lit, minimalist car showroom with uniform and soft lighting, creating a high-end and modern commercial photography atmosphere.

The overall composition is balanced, the colors are bright, the details are rich, and it is full of realism.', 'creative', '行者AI视频');
INSERT INTO prompts (title, content, category, author) VALUES ('E-commerce Main Image - Luxury Coffee Branding Product Photography', '"Luxury artisan coffee packaging, kraft paper bag with embossed gold lettering, dark roast beans in foreground, warm amber studio lighting, premium minimal brand identity, elegant serif typography, editorial product photography"', 'creative', 'SRKDAN');
INSERT INTO prompts (title, content, category, author) VALUES ('E-commerce Main Image - Luxury Snow Tire Image Generation', '"a snow tire in a super luxury and high-budget atmosphere"', 'creative', 'PSN用アカウント');
INSERT INTO prompts (title, content, category, author) VALUES ('Game Asset - Perler Bead Pattern Creator', 'Convert the image into a Perler bead pattern, preserving the pixel-style outlines and color distribution. Label each color area with its corresponding color code below the pattern. 1:1 image', 'general', 'Shinning');
INSERT INTO prompts (title, content, category, author) VALUES ('Game Asset - Heroic Nature-Punk Collage Poster', '{ "type": "image_prompt", "title": "Kaelen: The Verdant Whisper", "subject": { "character": "{argument name="character name" default="Kaelen"}", "source": "Original Character Concept", "focus": "legendary heroic propaganda poster" }, "composition": { "structure": { "top_section": { "description": "Large-scale symbolic portrait of Kaelen wearing a {argument name="accessory" default="leather steampunk mask and mechanical goggles"}", "purpose": "dominant emotional focal point" }, "middle_section": { "description": "Narrative collage featuring a glowing spirit tree, rebel silhouettes, and mechanical wildlife", "purpose": "world-building and lore fragments" }, "bottom_section": { "description": "Full-body grounding shot of Kaelen standing on a mossy peak with a druidic staff", "purpose": "central grounding and heroic posture" } }, "layout": { "style": "hierarchical editorial collage", "balance": "center-weighted vertical flow", "format": "9:16 vertical poster" } }, "visual_style": { "techniques": [ "double exposure", "ink wash diffusion", "layered visual storytelling" ], "elements": { "background_layers": [ "clean white negative space", "misty valley textures", "ink-splatter edges" ], "aesthetic": { "tone": "{argument name="aesthetic tone" default="Poetic Nature-Punk"}", "color_style": "Vibrant forest greens, deep earth tones, and electric blue energy pops", "quality": "8k, ultra-refined, cinematic editorial" } } }, "design_principles": [ "high negative space usage", "sharp focus on facial textures", "strong vertical continuity", "luxury magazine aesthetic" ] }', 'general', 'Minahil');
INSERT INTO prompts (title, content, category, author) VALUES ('Game Asset - Cyberpunk Neon Hacker', 'A {argument name="subject" default="young man with medium-length wavy silver hair"}, sharp jawline, light stubble, intense hazel eyes, wearing a futuristic hoodie, sitting in a {argument name="environment" default="neon-lit cyberpunk room"} full of holographic screens, glowing {argument name="colors" default="blue and pink lights"} reflecting on his face, dark moody atmosphere, ultra-detailed, cinematic lighting, 4K, cyberpunk aesthetic', 'general', 'Zoraiz Ai');
INSERT INTO prompts (title, content, category, author) VALUES ('Game Asset - Intricate Steampunk Mechanical Sculpture', '[{argument name="subject" default="subject"}] hyper-realistic {argument name="materials" default="intricate steampunk sculpture of that subject, masterfully crafted with polished brass, copper pipes, exposed gears"}, levers, valves, pressure gauges and Victorian mechanical details, rich metallic textures with patina and subtle wear, {argument name="lighting" default="dramatic studio lighting"} with strong specular highlights and deep shadows emphasizing every mechanical element, displayed on a dark wooden base, ultra detailed, photorealistic, masterpiece', 'general', 'Toshi');
INSERT INTO prompts (title, content, category, author) VALUES ('Game Asset - Gotham City Night Background', 'Ultra realistic cinematic {argument name="city style" default="Gotham-style city"} at night, wide angle 16:9 composition, viewed from a high rooftop perspective dense futuristic cityscape with gothic architecture, tall skyscrapers, neon signs, glowing windows, bridges and layered depth across the skyline heavy rain falling diagonally, wet surfaces reflecting light, atmospheric fog and volumetric haze creating depth lighting: dark moody scene with high contrast, deep blacks, cool blue-green color grading, subtle warm highlights from city lights sky: thick storm clouds with a soft glowing {argument name="sky signal" default="bat-shaped signal"} projected into the clouds, volumetric light beam, slightly diffused imperfect edges, realistic light scattering (not a sharp logo) composition: - bat signal positioned in upper right quadrant - dense skyline across middle - clear negative space in bottom-right foreground for a future character silhouette - visible gothic stone ledge in bottom-right corner with wet reflective surface camera: - slightly elevated cinematic angle - wide field of view - strong depth perspective (foreground, midground, background layers) style: photorealistic, hyper-detailed, Unreal Engine 5 quality, cinematic lighting, volumetric effects, high dynamic range important: no characters, no people, no superheroes visible no cartoon, no illustration, no comic style', 'general', 'Chaitanya Shetty | Tech Partner For Your Products');
